            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Tout au fond, l'esprit ne pense l'homme que dans l'éternel, et la conscience de la vie ne peut être qu'angoisse.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "il ne faut pas neuf mois, il faut soixante ans pour faire un homme, soixante ans de sacrifices, de volonté, de… de tant de choses ! Et quand cet homme est fait, quand il n'y a plus en lui rien de l'enfance, ni de l'adolescence, quand vraiment, il est homme, il n'est plus bon qu'à mourir.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "L'approche de la faillite apporte aux groupes financiers une conscience intense de la nation à laquelle ils appartiennent.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Les hommes ne sont pas mes semblables, ils sont ceux qui me regardent et me jugent ; mes semblables ce sont ceux qui m’aiment et ne me regardent pas, qui m’aiment contre tout, qui m’aiment contre la déchéance, contre la bassesse, contre la trahison, moi et non ce que j’ai fait ou ferai, qui m’aimeraient tant que je m’aimerais moi-même - jusqu’au suicide, compris…", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "La souffrance ne peut avoir de sens que quand elle ne mène pas à la mort, et elle y mène presque toujours.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Il n’y a pas de dignité possible, pas de vie réelle pour un homme qui travaille douze heures par jour sans savoir pourquoi il travaille.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Le marxisme n’est pas une doctrine, c’est une volonté, c’est, pour le prolétariat et les siens(…) la volonté de se connaitre, de se sentir comme tels ; vous ne devez pas être marxistes pour avoir raison, mais pour vaincre sans vous trahir.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "la tragédie de la mort est en ceci qu’elle transforme la vie en destin, qu’à partir d’elle rien ne peut plus être compensé.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "En profondeur, tout civilisation est unpénétrable pour une autre.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "La jeunesse est une religion dont il faut toujours finir par se convertir...", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "On ne pense pas sans danger contre la masse des hommes. Vers qui irais-je, sinon vers ceux qui se défendent comme moi?", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Que faire des cadavres des idées qui dominaient la conduite des hommes lorsqu'ils croyaient leur existence \"utile\" à quelque salut, que faire des paroles de ceux qui veulent soumettre leur vie à un modèle, ces autres cadavres? L'absence de finalité donnée à la vie était devenue une condition de l'action.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Se refuser sans réserves au monde, c'est toujours se faire souffrir terriblement pour se prouver sa force.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Vivante et morte comme lit d'un fleuve, la Voie Royale ne menait plus qu'aux vestiges que laissent derrière elles, tels des ossements, les migrations et les armées.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "La culture, c'est ce qui répond à l'homme quand il se demande ce qu'il fait sur la terre.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Comme Leclerc entra aux Invalides, avec son cortège d'exaltation dans le soleil d'Afrique, entre ici, Jean Moulin, avec ton terrible cortège. Avec ceux qui sont morts dans les caves sans avoir parlé, comme toi — et même, ce qui est peut-être plus atroce, en ayant parlé. Avec tous les rayés et tous les tondus des camps de concentration, avec le dernier corps trébuchant des affreuses files de Nuit et Brouillard, enfin tombé sous les crosses. Avec les huit mille Françaises qui ne sont pas revenues des bagnes, avec la dernière femme morte à Ravensbrück pour avoir donné asile à l'un des nôtres. Entre avec le peuple né de l'ombre et disparu avec elle — nos frères dans l'ordre de la Nuit…", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "Aujourd'hui, jeunesse, puisses-tu penser à cet homme comme tu aurais approché tes mains de sa pauvre face informe du dernier jour, de ses lèvres qui n'avaient pas parlé ; ce jour-là, elle était le visage de la France.", Author = "André Malraux" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/André_Malraux", Text = "La liberté appartient d'abord à ceux qui l'ont conquise.", Author = "André Malraux" },
